import React, { useState } from 'react';

// Định nghĩa kiểu dữ liệu cho bộ lọc để dùng ở các trang khác
export interface FilterCriteria {
    minPrice: number;
    maxPrice: number;
    brands: string[];
    stars: number[];
}

const SidebarFilter = () => {
    // 1. State quản lý giá
    const [priceRange, setPriceRange] = useState({ min: 0, max: 5000000 });
    
    // 2. State quản lý Hãng (chọn nhiều nên dùng mảng)
    const [selectedBrands, setSelectedBrands] = useState<string[]>([]);
    const brandsList = ['Vinpearl', 'Mường Thanh', 'FLC', 'Novotel', 'InterContinental'];

    // 3. State quản lý Số sao
    const [selectedStars, setSelectedStars] = useState<number[]>([]);
    const starsList = [5, 4, 3, 2, 1];

    // Hàm xử lý khi tick/untick checkbox
    const handleToggle = (item: any, list: any[], setList: Function) => {
        if (list.includes(item)) {
            setList(list.filter(i => i !== item));
        } else {
            setList([...list, item]);
        }
    };

    const handleApply = () => {
        const finalFilters: FilterCriteria = {
            minPrice: priceRange.min,
            maxPrice: priceRange.max,
            brands: selectedBrands,
            stars: selectedStars
        };
        console.log("Dữ liệu gửi đi lọc nè Liên:", finalFilters);
        alert("Đã áp dụng bộ lọc! Check console để xem data nhé.");
    };

    return (
        <aside style={sidebarStyle}>
            <h3 style={{ fontSize: '18px', fontWeight: '700', marginBottom: '20px' }}>Bộ lọc tìm kiếm</h3>

            {/* --- PHẦN 1: KHOẢNG GIÁ --- */}
            <div style={sectionStyle}>
                <p style={labelStyle}>Khoảng giá (VND)</p>
                <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                    <input 
                        type="number" 
                        placeholder="Từ" 
                        style={inputStyle}
                        onChange={(e) => setPriceRange({...priceRange, min: Number(e.target.value)})}
                    />
                    <span>-</span>
                    <input 
                        type="number" 
                        placeholder="Đến" 
                        style={inputStyle}
                        onChange={(e) => setPriceRange({...priceRange, max: Number(e.target.value)})}
                    />
                </div>
            </div>

            {/* --- PHẦN 2: HÃNG / THƯƠNG HIỆU --- */}
            <div style={sectionStyle}>
                <p style={labelStyle}>Thương hiệu</p>
                {brandsList.map(brand => (
                    <label key={brand} style={checkboxLabelStyle}>
                        <input 
                            type="checkbox" 
                            checked={selectedBrands.includes(brand)}
                            onChange={() => handleToggle(brand, selectedBrands, setSelectedBrands)}
                        />
                        <span style={{ marginLeft: '8px' }}>{brand}</span>
                    </label>
                ))}
            </div>

            {/* --- PHẦN 3: HẠNG SAO --- */}
            <div style={sectionStyle}>
                <p style={labelStyle}>Hạng sao</p>
                {starsList.map(star => (
                    <label key={star} style={checkboxLabelStyle}>
                        <input 
                            type="checkbox" 
                            checked={selectedStars.includes(star)}
                            onChange={() => handleToggle(star, selectedStars, setSelectedStars)}
                        />
                        <span style={{ marginLeft: '8px' }}>{star} Sao { '⭐'.repeat(star) }</span>
                    </label>
                ))}
            </div>

            {/* NÚT ÁP DỤNG */}
            <button onClick={handleApply} style={buttonStyle}>
                Áp dụng bộ lọc
            </button>
            
            <button 
                onClick={() => {setSelectedBrands([]); setSelectedStars([]);}}
                style={{ ...buttonStyle, backgroundColor: 'white', color: '#007bff', marginTop: '10px', border: '1px solid #007bff' }}
            >
                Xóa tất cả
            </button>
        </aside>
    );
};

// --- CSS IN JS (Để Liên copy phát chạy luôn không cần file CSS riêng) ---
const sidebarStyle: React.CSSProperties = {
    width: '280px',
    padding: '20px',
    backgroundColor: '#fff',
    borderRadius: '12px',
    boxShadow: '0 4px 12px rgba(0,0,0,0.05)',
    border: '1px solid #eee',
    height: 'fit-content'
};

const sectionStyle = { marginBottom: '25px' };
const labelStyle = { fontWeight: 'bold', marginBottom: '12px', fontSize: '14px', color: '#333' };
const inputStyle = { width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ddd', fontSize: '13px' };
const checkboxLabelStyle = { display: 'flex', alignItems: 'center', marginBottom: '8px', cursor: 'pointer', fontSize: '14px' };
const buttonStyle = { 
    width: '100%', padding: '12px', backgroundColor: '#007bff', color: '#fff', 
    border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', transition: '0.3s' 
};

export default SidebarFilter;

import React, { createContext, useContext, useState, useEffect } from 'react';
import type { ReactNode } from 'react';
import { authApi } from '../services/authApi';

export interface User { id: string; Ho: string; Ten: string; Email: string; }

interface AuthContextType {
    user: User | null;
    isAuthenticated: boolean;
    isLoading: boolean;
    login: (credentials: any) => Promise<void>;
    register: (data: any) => Promise<void>;
    logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const storedUser = localStorage.getItem('user');
        const token = localStorage.getItem('token');
        if (storedUser && token) setUser(JSON.parse(storedUser));
        setIsLoading(false);
    }, []);

    const login = async (credentials: any) => {
        setIsLoading(true);
        try {
            const data = await authApi.login(credentials);
            setUser(data.user);
            localStorage.setItem('user', JSON.stringify(data.user));
            localStorage.setItem('token', data.token);
        } finally { setIsLoading(false); }
    };

    const register = async (data: any) => {
        setIsLoading(true);
        try {
            const result = await authApi.register(data);
            setUser(result.user);
            localStorage.setItem('user', JSON.stringify(result.user));
            localStorage.setItem('token', result.token);
        } finally { setIsLoading(false); }
    };

    const logout = () => { setUser(null); localStorage.removeItem('user'); localStorage.removeItem('token'); };

    return (
        <AuthContext.Provider value={{ user, isAuthenticated: !!user, isLoading, login, register, logout }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (!context) throw new Error('useAuth must be used within AuthProvider');
    return context;
};

import React, { createContext, useContext, useState } from 'react';
import type { ReactNode } from 'react';

// Types
export interface Flight {
    id: string;
    airline: string;
    flightNumber: string;
    from: string;
    to: string;
    departureTime: string;
    arrivalTime: string;
    duration: number;
    price: number;
    seatClass: string;
    availableSeats: number;
}

export interface Hotel {
    id: string;
    name: string;
    location: string;
    address: string;
    rating: number;
    pricePerNight: number;
    checkIn: string;
    checkOut: string;
    rooms: number;
    amenities: string[];
    image?: string;
}

export interface Bus {
    id: string;
    company: string;
    from: string;
    to: string;
    departureTime: string;
    arrivalTime: string;
    price: number;
    seatType: string;
    availableSeats: number;
}

export type BookingStep = 'search' | 'select' | 'details' | 'payment' | 'confirmation';

interface BookingContextType {
    // Selected items
    selectedFlight: Flight | null;
    selectedHotel: Hotel | null;
    selectedBus: Bus | null;

    // Booking flow
    currentStep: BookingStep;

    // Actions
    selectFlight: (flight: Flight) => void;
    selectHotel: (hotel: Hotel) => void;
    selectBus: (bus: Bus) => void;

    clearFlight: () => void;
    clearHotel: () => void;
    clearBus: () => void;
    clearAll: () => void;

    setStep: (step: BookingStep) => void;
    nextStep: () => void;
    previousStep: () => void;

    // Computed
    getTotalPrice: () => number;
    hasSelections: () => boolean;
}

// Create Context
const BookingContext = createContext<BookingContextType | undefined>(undefined);

// Provider Component
export const BookingProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [selectedFlight, setSelectedFlight] = useState<Flight | null>(null);
    const [selectedHotel, setSelectedHotel] = useState<Hotel | null>(null);
    const [selectedBus, setSelectedBus] = useState<Bus | null>(null);
    const [currentStep, setCurrentStep] = useState<BookingStep>('search');

    const selectFlight = (flight: Flight) => {
        setSelectedFlight(flight);
    };

    const selectHotel = (hotel: Hotel) => {
        setSelectedHotel(hotel);
    };

    const selectBus = (bus: Bus) => {
        setSelectedBus(bus);
    };

    const clearFlight = () => {
        setSelectedFlight(null);
    };

    const clearHotel = () => {
        setSelectedHotel(null);
    };

    const clearBus = () => {
        setSelectedBus(null);
    };

    const clearAll = () => {
        setSelectedFlight(null);
        setSelectedHotel(null);
        setSelectedBus(null);
        setCurrentStep('search');
    };

    const setStep = (step: BookingStep) => {
        setCurrentStep(step);
    };

    const steps: BookingStep[] = ['search', 'select', 'details', 'payment', 'confirmation'];

    const nextStep = () => {
        const currentIndex = steps.indexOf(currentStep);
        if (currentIndex < steps.length - 1) {
            setCurrentStep(steps[currentIndex + 1]);
        }
    };

    const previousStep = () => {
        const currentIndex = steps.indexOf(currentStep);
        if (currentIndex > 0) {
            setCurrentStep(steps[currentIndex - 1]);
        }
    };

    const getTotalPrice = (): number => {
        let total = 0;
        if (selectedFlight) total += selectedFlight.price;
        if (selectedHotel) {
            const nights = selectedHotel.checkOut && selectedHotel.checkIn
                ? Math.ceil((new Date(selectedHotel.checkOut).getTime() - new Date(selectedHotel.checkIn).getTime()) / (1000 * 60 * 60 * 24))
                : 1;
            total += selectedHotel.pricePerNight * nights * selectedHotel.rooms;
        }
        if (selectedBus) total += selectedBus.price;
        return total;
    };

    const hasSelections = (): boolean => {
        return !!(selectedFlight || selectedHotel || selectedBus);
    };

    const value: BookingContextType = {
        selectedFlight,
        selectedHotel,
        selectedBus,
        currentStep,
        selectFlight,
        selectHotel,
        selectBus,
        clearFlight,
        clearHotel,
        clearBus,
        clearAll,
        setStep,
        nextStep,
        previousStep,
        getTotalPrice,
        hasSelections,
    };

    return <BookingContext.Provider value={value}>{children}</BookingContext.Provider>;
};

// Custom Hook
export const useBooking = (): BookingContextType => {
    const context = useContext(BookingContext);
    if (!context) {
        throw new Error('useBooking must be used within BookingProvider');
    }
    return context;
};

