import React, { createContext, useContext, useState, useCallback } from 'react';
import type { ReactNode } from 'react';

// Types
export type NotificationType = 'success' | 'error' | 'warning' | 'info';

export interface Notification {
    id: string;
    type: NotificationType;
    message: string;
    duration?: number;
}

interface NotificationContextType {
    notifications: Notification[];
    showSuccess: (message: string, duration?: number) => void;
    showError: (message: string, duration?: number) => void;
    showWarning: (message: string, duration?: number) => void;
    showInfo: (message: string, duration?: number) => void;
    removeNotification: (id: string) => void;
    clearAll: () => void;
}

// Create Context
const NotificationContext = createContext<NotificationContextType | undefined>(undefined);

// Provider Component
export const NotificationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [notifications, setNotifications] = useState<Notification[]>([]);

    const addNotification = useCallback(
        (type: NotificationType, message: string, duration: number = 5000) => {
            const id = `notification-${Date.now()}-${Math.random()}`;

            const notification: Notification = {
                id,
                type,
                message,
                duration,
            };

            setNotifications((prev) => [...prev, notification]);

            // Auto remove after duration
            if (duration > 0) {
                setTimeout(() => {
                    removeNotification(id);
                }, duration);
            }

            return id;
        },
        []
    );

    const removeNotification = useCallback((id: string) => {
        setNotifications((prev) => prev.filter((notif) => notif.id !== id));
    }, []);

    const clearAll = useCallback(() => {
        setNotifications([]);
    }, []);

    const showSuccess = useCallback(
        (message: string, duration?: number) => {
            addNotification('success', message, duration);
        },
        [addNotification]
    );

    const showError = useCallback(
        (message: string, duration?: number) => {
            addNotification('error', message, duration);
        },
        [addNotification]
    );

    const showWarning = useCallback(
        (message: string, duration?: number) => {
            addNotification('warning', message, duration);
        },
        [addNotification]
    );

    const showInfo = useCallback(
        (message: string, duration?: number) => {
            addNotification('info', message, duration);
        },
        [addNotification]
    );

    const value: NotificationContextType = {
        notifications,
        showSuccess,
        showError,
        showWarning,
        showInfo,
        removeNotification,
        clearAll,
    };

    return <NotificationContext.Provider value={value}>{children}</NotificationContext.Provider>;
};

// Custom Hook
export const useNotification = (): NotificationContextType => {
    const context = useContext(NotificationContext);
    if (!context) {
        throw new Error('useNotification must be used within NotificationProvider');
    }
    return context;
};

import React, { createContext, useContext, useState } from 'react';
import type { ReactNode } from 'react';

// Types
export interface SearchParams {
    type: 'flight' | 'hotel' | 'bus' | 'transfer' | 'car' | null;
    from?: string;
    to?: string;
    destination?: string;
    checkIn?: string;
    checkOut?: string;
    departureDate?: string;
    returnDate?: string;
    passengers?: number;
    adults?: number;
    children?: number;
    rooms?: number;
    seatClass?: 'economy' | 'business' | 'first';
}

export interface SearchFilters {
    priceRange?: [number, number];
    rating?: number;
    airline?: string[];
    hotelType?: string[];
    amenities?: string[];
    sortBy?: 'price' | 'rating' | 'duration' | 'departure';
    sortOrder?: 'asc' | 'desc';
}

interface SearchContextType {
    searchParams: SearchParams;
    filters: SearchFilters;
    setSearchParams: (params: Partial<SearchParams>) => void;
    setFilters: (filters: Partial<SearchFilters>) => void;
    resetSearch: () => void;
    resetFilters: () => void;
}

// Default values
const defaultSearchParams: SearchParams = {
    type: null,
    passengers: 1,
    adults: 1,
    children: 0,
    rooms: 1,
};

const defaultFilters: SearchFilters = {
    sortBy: 'price',
    sortOrder: 'asc',
};

// Create Context
const SearchContext = createContext<SearchContextType | undefined>(undefined);

// Provider Component
export const SearchProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [searchParams, setSearchParamsState] = useState<SearchParams>(defaultSearchParams);
    const [filters, setFiltersState] = useState<SearchFilters>(defaultFilters);

    const setSearchParams = (params: Partial<SearchParams>) => {
        setSearchParamsState((prev) => ({ ...prev, ...params }));
    };

    const setFilters = (newFilters: Partial<SearchFilters>) => {
        setFiltersState((prev) => ({ ...prev, ...newFilters }));
    };

    const resetSearch = () => {
        setSearchParamsState(defaultSearchParams);
    };

    const resetFilters = () => {
        setFiltersState(defaultFilters);
    };

    const value: SearchContextType = {
        searchParams,
        filters,
        setSearchParams,
        setFilters,
        resetSearch,
        resetFilters,
    };

    return <SearchContext.Provider value={value}>{children}</SearchContext.Provider>;
};

// Custom Hook
export const useSearch = (): SearchContextType => {
    const context = useContext(SearchContext);
    if (!context) {
        throw new Error('useSearch must be used within SearchProvider');
    }
    return context;
};

import { useEffect, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';

export interface UrlFilters {
    // Query chung
    query?: string;
    // Filters
    from?: string;
    to?: string;
    destination?: string;
    date?: string;
    returnDate?: string;
    checkIn?: string;
    checkOut?: string;
    passengers?: string;
    adults?: string;
    children?: string;
    rooms?: string;
    priceMin?: string;
    priceMax?: string;
    rating?: string;
    sortBy?: string;
    sortOrder?: string;
    // Pagination
    page?: string;
    pageSize?: string;
}

/**
 * Hook dùng chung để đọc/ghi filters + pagination vào URL.
 * 
 * Cách dùng:
 *   const { filters, setFilter, setPage, resetFilters } = useUrlFilters();
 */
export function useUrlFilters() {
    const [searchParams, setSearchParams] = useSearchParams();

    // Đọc tất cả filters từ URL thành object
    const filters: UrlFilters = {
        query: searchParams.get('query') ?? undefined,
        from: searchParams.get('from') ?? undefined,
        to: searchParams.get('to') ?? undefined,
        destination: searchParams.get('destination') ?? undefined,
        date: searchParams.get('date') ?? undefined,
        returnDate: searchParams.get('returnDate') ?? undefined,
        checkIn: searchParams.get('checkIn') ?? undefined,
        checkOut: searchParams.get('checkOut') ?? undefined,
        passengers: searchParams.get('passengers') ?? undefined,
        adults: searchParams.get('adults') ?? undefined,
        children: searchParams.get('children') ?? undefined,
        rooms: searchParams.get('rooms') ?? undefined,
        priceMin: searchParams.get('priceMin') ?? undefined,
        priceMax: searchParams.get('priceMax') ?? undefined,
        rating: searchParams.get('rating') ?? undefined,
        sortBy: searchParams.get('sortBy') ?? undefined,
        sortOrder: searchParams.get('sortOrder') ?? undefined,
        page: searchParams.get('page') ?? '1',
        pageSize: searchParams.get('pageSize') ?? '10',
    };

    /** Cập nhật một hoặc nhiều filter, tự reset về trang 1 */
    const setFilter = useCallback((newFilters: Partial<UrlFilters>) => {
        setSearchParams(prev => {
            const next = new URLSearchParams(prev);
            Object.entries(newFilters).forEach(([key, value]) => {
                if (value === undefined || value === null || value === '') {
                    next.delete(key);
                } else {
                    next.set(key, String(value));
                }
            });
            // Reset về trang 1 khi đổi filter (trừ khi đang set page)
            if (!('page' in newFilters)) {
                next.set('page', '1');
            }
            return next;
        });
    }, [setSearchParams]);

    /** Chuyển trang (chỉ đổi page, giữ nguyên các filter khác) */
    const setPage = useCallback((page: number) => {
        setSearchParams(prev => {
            const next = new URLSearchParams(prev);
            next.set('page', String(page));
            return next;
        });
    }, [setSearchParams]);

    /** Xóa toàn bộ filters, về trang 1 */
    const resetFilters = useCallback(() => {
        setSearchParams({});
    }, [setSearchParams]);

    // Helper: lấy page number dưới dạng số
    const currentPage = Number(filters.page) || 1;
    const currentPageSize = Number(filters.pageSize) || 10;

    return {
        filters,
        setFilter,
        setPage,
        resetFilters,
        currentPage,
        currentPageSize,
    };
}

